let adjustmentItems = new Map();
const byId = id => document.getElementById(id);
function setOperationMessage(text='') { const el=byId('operation-form-message'); el.textContent=text; el.classList.toggle('hidden',!text); }
function openModal(id) { const modal=byId(id); modal.classList.remove('hidden'); modal.classList.add('flex'); }
function closeModal(id) { const modal=byId(id); modal.classList.add('hidden'); modal.classList.remove('flex'); }
function exactProductLabel(product){return `${product.name} · ${product.variant} · ${product.size} · Barcode: ${product.barcode}`;}
function updateOfflineTotal(){
    const total=[...operationItems.entries()].reduce((sum,[id,quantity])=>sum+(Number(operationPrices.get(id)??productById.get(id)?.price??0)*quantity),0);
    const output=byId('operation-total');
    if(output)output.textContent=`₱${total.toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
}
let selectedOperationProductId=null;
let selectedAdjustmentProductId=null;
function selectOperationProduct(product){if(!product)return;selectedOperationProductId=Number(product.id);byId('operation-product-select').value=String(product.id);const source=warehouseOperationConfig[operationType]?.source;const stock=source==='pos'?Number(product.pos):Number(product.warehouse);const already=Number(operationItems.get(Number(product.id))||0);const available=source===null?null:Math.max(0,stock-already);byId('operation-product-stock').textContent=available===null?`${exactProductLabel(product)} · Current Warehouse Stock: ${stock}`:`${exactProductLabel(product)} · Available ${source==='pos'?'POS':'Warehouse'} Stock: ${available}`;byId('operation-manual-quantity').value='1';byId('operation-manual-quantity').max=available===null?'':String(available);byId('add-operation-item').disabled=available===0;}
byId('operation-product-select').addEventListener('change',()=>{const id=Number(byId('operation-product-select').value);if(!id){selectedOperationProductId=null;byId('add-operation-item').disabled=true;byId('operation-product-stock').textContent='Select one exact product from the list.';return;}selectOperationProduct(productById.get(id));});
function openOperation(type) {
    operationType=type; operationItems=new Map(); operationPrices=new Map(); setOperationMessage('');
    const config=warehouseOperationConfig[type]; if(!config)return;
    byId('operation-form-items').replaceChildren();
    byId('warehouse-operation-form').querySelector('[name="submission_key"]').value=window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
    byId('warehouse-operation-form').action=warehouseOperationRoutes[type];
    byId('operationTitle').textContent=config.title; byId('operationDescription').textContent=config.description; byId('submit-operation').textContent=config.submit;
    selectedOperationProductId=null;byId('operation-product-select').value='';byId('operation-manual-quantity').value='1';byId('operation-barcode').value='';byId('add-operation-item').disabled=true;byId('operation-product-stock').textContent='Select an exact product, variant, size, and barcode.';
    const specificFields=byId('operation-specific-fields');specificFields.replaceChildren();if(config.customer)specificFields.append(byId('offline-sale-fields-template').content.cloneNode(true));
    byId('operation-reason-fields').classList.toggle('hidden',!config.reason);byId('operation-reason').required=Boolean(config.reason);byId('operation-reason').value='';
    const payment=byId('operation-payment');if(payment)payment.value='cash';
    const qrConfirmation=byId('warehouse-qr-confirmed');if(qrConfirmation){qrConfirmation.checked=false;qrConfirmation.disabled=true;}
    byId('warehouse-qr-wrap')?.classList.add('hidden');
    byId('operation-help').textContent=config.source==='warehouse'?'Warehouse stock is checked again when this transaction is completed.':config.source==='pos'?'Available POS stock is checked again when returned to Warehouse.':'Warehouse stock changes only after the transaction is completed.';
    renderOperationItems(); openModal('warehouseOperationModal');byId('operation-barcode').focus();
}
document.querySelectorAll('[data-open-operation]').forEach(button=>button.addEventListener('click',()=>{button.closest('details')?.removeAttribute('open');openOperation(button.dataset.openOperation);}));
document.querySelectorAll('[data-close-operation]').forEach(button=>button.addEventListener('click',()=>closeModal('warehouseOperationModal')));
function showAdjustmentStock(product){selectedAdjustmentProductId=Number(product.id);byId('adjustment-product-select').value=String(product.id);byId('adjustment-current-stock').textContent=`${exactProductLabel(product)} · Current Warehouse Stock: ${product.warehouse} units`;byId('add-adjustment-item').disabled=false;}
function selectAdjustmentProduct(product){if(!product)return;byId('adjustment-barcode').value='';showAdjustmentStock(product);}
function clearAdjustmentSelection(message='Select an exact product, variant, size, and barcode.'){selectedAdjustmentProductId=null;byId('adjustment-product-select').value='';byId('adjustment-actual-stock').value='';byId('add-adjustment-item').disabled=true;byId('adjustment-current-stock').textContent=message;}
byId('adjustment-product-select').addEventListener('change',()=>{const id=Number(byId('adjustment-product-select').value);if(!id){clearAdjustmentSelection('Select an exact product from the list.');return;}showAdjustmentStock(productById.get(id));});
function renderAdjustmentItems(){const entries=[...adjustmentItems.entries()];const list=byId('adjustment-items');list.classList.toggle('hidden',entries.length===0);byId('adjustment-selected-heading').classList.toggle('hidden',entries.length===0);byId('add-another-adjustment-product').classList.toggle('hidden',entries.length===0);byId('submit-adjustment').disabled=entries.length===0;byId('adjustment-hidden-items').innerHTML=entries.map(([id,actual])=>`<input type="hidden" name="items[${id}]" value="${actual}">`).join('');list.innerHTML=entries.map(([id,actual])=>{const product=productById.get(id);return `<div class="flex flex-wrap items-center justify-between gap-2 px-3 py-2"><div class="min-w-0"><p class="truncate text-sm font-semibold">${escapeHtml(product.name)} · ${escapeHtml(product.variant)} · ${escapeHtml(product.size)}</p><p class="font-mono text-[10px] text-secondary">Barcode: ${escapeHtml(product.barcode)} · Current Stock: ${product.warehouse}</p></div><div class="flex items-center gap-2"><label class="text-xs text-secondary">Actual Stock<input class="form-input adjustment-actual mt-1 w-24 text-center" type="number" min="0" step="1" data-id="${id}" value="${actual}"></label><button type="button" class="remove-adjustment rounded p-2 text-error" data-id="${id}" aria-label="Remove adjustment item">×</button></div></div>`;}).join('');list.querySelectorAll('.adjustment-actual').forEach(input=>input.addEventListener('change',()=>{const actual=Number(input.value);if(!Number.isInteger(actual)||actual<0){input.value=String(adjustmentItems.get(Number(input.dataset.id)));return;}adjustmentItems.set(Number(input.dataset.id),actual);renderAdjustmentItems();}));list.querySelectorAll('.remove-adjustment').forEach(button=>button.addEventListener('click',()=>{adjustmentItems.delete(Number(button.dataset.id));renderAdjustmentItems();}));}
function openAdjustment(){adjustmentItems=new Map();byId('adjustment-form').querySelector('[name="submission_key"]').value=window.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;byId('adjustment-barcode').value='';clearAdjustmentSelection('Scan a barcode or select an exact product from the list.');byId('adjustment-message').classList.add('hidden');renderAdjustmentItems();openModal('adjustmentModal');byId('adjustment-barcode').focus();}
document.querySelectorAll('[data-open-adjustment]').forEach(button=>button.addEventListener('click',()=>openAdjustment()));
document.querySelectorAll('[data-close-adjustment]').forEach(button=>button.addEventListener('click',()=>closeModal('adjustmentModal')));
function updateOfflinePaymentFields(){const qr=byId('operation-payment')?.value==='qr';byId('warehouse-qr-wrap')?.classList.toggle('hidden',!qr);const confirmation=byId('warehouse-qr-confirmed');if(confirmation){confirmation.disabled=!qr;confirmation.required=qr;}}
byId('operation-specific-fields').addEventListener('change',event=>{if(event.target.id==='operation-payment')updateOfflinePaymentFields();});
function addScannedOperationProduct(product){const source=warehouseOperationConfig[operationType]?.source;const available=source==='pos'?Number(product.pos):source==='warehouse'?Number(product.warehouse):Infinity;const current=Number(operationItems.get(Number(product.id))||0);if(current+1>available){setOperationMessage(`No additional units are available in ${source==='pos'?'POS':'Warehouse'} stock for ${product.name}, ${product.size}.`);return false;}operationItems.set(Number(product.id),current+1);if(operationType==='offline_sale'&&!operationPrices.has(Number(product.id)))operationPrices.set(Number(product.id),Number(product.price));setOperationMessage('');renderOperationItems();selectedOperationProductId=null;byId('operation-product-select').value='';byId('add-operation-item').disabled=true;byId('operation-product-stock').textContent=`Added 1: ${exactProductLabel(product)} · Quantity ${current+1}.`;return true;}
function processOperationBarcode(){const input=byId('operation-barcode');const code=input.value.trim();if(!code)return;input.value='';if(!/^[0-9]{8}$/.test(code)){setOperationMessage('Scan a valid 8-digit numeric barcode.');return;}const product=warehouseProducts.find(item=>item.barcode===code);if(!product){setOperationMessage('Barcode not found or product is inactive.');return;}addScannedOperationProduct(product);input.focus();}
let operationScanTimer=null;byId('operation-barcode').addEventListener('input',()=>{const input=byId('operation-barcode');const numeric=input.value.replace(/\D/g,'').slice(0,8);if(input.value!==numeric)input.value=numeric;clearTimeout(operationScanTimer);if(/^[0-9]{8}$/.test(numeric))operationScanTimer=setTimeout(processOperationBarcode,140);});
byId('operation-barcode').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();clearTimeout(operationScanTimer);processOperationBarcode();}});

byId('add-adjustment-item').addEventListener('click',()=>{const id=selectedAdjustmentProductId;const actual=Number(byId('adjustment-actual-stock').value);const message=byId('adjustment-message');if(!id||!Number.isInteger(actual)||actual<0){message.textContent='Select an exact product and enter its Actual Stock.';message.classList.remove('hidden');return;}adjustmentItems.set(id,actual);message.classList.add('hidden');renderAdjustmentItems();clearAdjustmentSelection('Product added. Choose another product or complete the adjustment.');byId('adjustment-product-select').focus();});
byId('add-another-adjustment-product').addEventListener('click',()=>{clearAdjustmentSelection('Choose another exact product, variant, size, and barcode.');byId('adjustment-product-select').focus();});
function processAdjustmentBarcode(){const input=byId('adjustment-barcode');const code=input.value.trim();if(!code)return;input.value='';const product=/^[0-9]{8}$/.test(code)?warehouseProducts.find(item=>item.barcode===code):null;if(!product){selectedAdjustmentProductId=null;byId('add-adjustment-item').disabled=true;byId('adjustment-current-stock').textContent='Barcode not found or enter a valid 8-digit numeric barcode.';return;}selectAdjustmentProduct(product);byId('adjustment-actual-stock').focus();}
let adjustmentScanTimer=null;byId('adjustment-barcode').addEventListener('input',()=>{const input=byId('adjustment-barcode');const numeric=input.value.replace(/\D/g,'').slice(0,8);if(input.value!==numeric)input.value=numeric;clearTimeout(adjustmentScanTimer);if(/^[0-9]{8}$/.test(numeric))adjustmentScanTimer=setTimeout(processAdjustmentBarcode,140);});
byId('adjustment-barcode').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();clearTimeout(adjustmentScanTimer);processAdjustmentBarcode();}});
function renderOperationItems() {
    const list=byId('operation-item-list');const entries=[...operationItems.entries()];list.classList.toggle('hidden',entries.length===0);byId('operation-selected-heading').classList.toggle('hidden',entries.length===0);
    byId('add-another-operation-product').classList.toggle('hidden',entries.length===0);
    byId('operation-form-items').innerHTML=entries.map(([id,quantity])=>`<input type="hidden" name="items[${id}]" value="${quantity}">${operationType==='offline_sale'?`<input type="hidden" name="prices[${id}]" value="${Number(operationPrices.get(id)??productById.get(id).price).toFixed(2)}">`:''}`).join('');
    list.innerHTML=entries.map(([id,quantity])=>{const product=productById.get(id);const price=operationPrices.get(id)??product.price;const source=warehouseOperationConfig[operationType]?.source;const stockQuantity=source==='pos'?Number(product.pos):Number(product.warehouse);const available=source===null?stockQuantity:Math.max(0,stockQuantity-quantity);const stockText=source===null?`Current Warehouse Stock: ${stockQuantity} unit(s)`:`Available ${source==='pos'?'POS':'Warehouse'} Stock: ${available} unit(s) remaining`;const saleFields=operationType==='offline_sale'?`<label class="text-xs text-secondary">Selling Price<input class="form-input operation-price mt-1 w-32" data-id="${id}" type="number" min="0" step="0.01" value="${Number(price).toFixed(2)}" aria-label="Selling price for ${escapeHtml(product.name)} ${escapeHtml(product.variant)} ${escapeHtml(product.size)}"><span class="mt-1 block font-semibold text-on-surface">Line Total: ₱${(Number(price)*quantity).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}</span></label>`:'';return `<div class="flex flex-col justify-between gap-3 px-3 py-2 sm:flex-row sm:items-center"><div class="min-w-0"><p class="truncate text-sm font-semibold">${escapeHtml(product.name)} · ${escapeHtml(product.variant)} · ${escapeHtml(product.size)}</p><p class="font-mono text-[10px] text-secondary">Barcode: ${escapeHtml(product.barcode)} · ${stockText}</p></div><div class="flex flex-wrap items-end gap-3"><label class="text-xs font-semibold text-secondary">Quantity<input class="form-input operation-quantity mt-1 w-20 text-center" data-id="${id}" type="number" min="1" ${source===null?'':`max="${stockQuantity}"`} step="1" value="${quantity}" aria-label="Quantity for ${escapeHtml(product.name)} ${escapeHtml(product.variant)} ${escapeHtml(product.size)}"></label>${saleFields}<button type="button" class="remove-operation-item rounded p-1 text-secondary hover:bg-surface-container-low hover:text-error" data-id="${id}" aria-label="Remove item"><span class="material-symbols-outlined text-base">delete</span></button></div></div>`;}).join('');
    list.querySelectorAll('.operation-quantity').forEach(input=>input.addEventListener('change',()=>{const id=Number(input.dataset.id);const product=productById.get(id);const quantity=Number(input.value);const source=warehouseOperationConfig[operationType]?.source;const maximum=source==='pos'?Number(product.pos):source==='warehouse'?Number(product.warehouse):Infinity;if(!Number.isInteger(quantity)||quantity<1||quantity>maximum){input.value=String(operationItems.get(id));setOperationMessage(`Enter a whole quantity from 1 to ${Number.isFinite(maximum)?maximum:'a valid amount'} for ${product.name}, ${product.size}.`);return;}operationItems.set(id,quantity);setOperationMessage('');renderOperationItems();}));
    list.querySelectorAll('.remove-operation-item').forEach(button=>button.addEventListener('click',()=>{const id=Number(button.dataset.id);operationItems.delete(id);operationPrices.delete(id);renderOperationItems();}));
    list.querySelectorAll('.operation-price').forEach(input=>input.addEventListener('input',()=>{operationPrices.set(Number(input.dataset.id),Number(input.value||0));const line=input.parentElement.querySelector('span');line.textContent=`Line Total: ₱${(Number(input.value||0)*(operationItems.get(Number(input.dataset.id))||0)).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;byId('operation-form-items').querySelector(`[name="prices[${input.dataset.id}]"]`).value=Number(input.value||0).toFixed(2);updateOfflineTotal();}));
    updateOfflineTotal();
}
byId('add-another-operation-product').addEventListener('click',()=>{selectedOperationProductId=null;byId('operation-product-select').value='';byId('operation-manual-quantity').value='1';byId('add-operation-item').disabled=true;byId('operation-product-stock').textContent='Select another exact product from the list.';byId('operation-product-select').focus();});
function addManualOperationProduct(){const id=selectedOperationProductId;const quantity=Number(byId('operation-manual-quantity').value);const product=productById.get(Number(id));if(!product||!Number.isInteger(quantity)||quantity<1){setOperationMessage('Choose an exact product and enter a whole quantity.');return;}const source=warehouseOperationConfig[operationType]?.source;const stock=source==='pos'?Number(product.pos):source==='warehouse'?Number(product.warehouse):Infinity;const next=Number(operationItems.get(Number(id))||0)+quantity;if(next>stock){setOperationMessage(`Only ${Math.max(0,stock-Number(operationItems.get(Number(id))||0))} more unit(s) are available for ${product.name}, ${product.size}.`);return;}operationItems.set(Number(id),next);if(operationType==='offline_sale'&&!operationPrices.has(Number(id)))operationPrices.set(Number(id),Number(product.price));setOperationMessage('');renderOperationItems();selectedOperationProductId=null;byId('operation-product-select').value='';byId('operation-manual-quantity').value='1';byId('add-operation-item').disabled=true;byId('operation-product-stock').textContent='Product added. Select another product or complete the transaction.';byId('operation-product-select').focus();}
byId('add-operation-item').addEventListener('click',addManualOperationProduct);
byId('operation-reason').addEventListener('change',()=>{const others=byId('operation-reason').value==='Others';const notes=byId('operation-notes-wrap');if(others&&!notes)byId('operation-specific-fields').append(byId('withdrawal-notes-template').content.cloneNode(true));else if(!others)notes?.remove();});
byId('warehouse-operation-form').addEventListener('submit',event=>{
    const message=[];const config=warehouseOperationConfig[operationType];if(operationItems.size===0)message.push('Add at least one product.');if(config.customer&&!byId('operation-customer')?.value.trim())message.push('Enter the customer name.');if(config.reason&&!byId('operation-reason').value)message.push('Select a withdrawal reason.');if(config.reason&&byId('operation-reason').value==='Others'&&!byId('operation-notes')?.value.trim())message.push('Add notes when Others is selected.');if(config.payment&&byId('operation-payment').value==='qr'&&!byId('warehouse-qr-confirmed')?.checked)message.push('Confirm the QR payment before completing the sale.');
    if(message.length){event.preventDefault();setOperationMessage(message.join(' '));return;}
    byId('submit-operation').disabled=true;byId('submit-operation').textContent='Completing…';
});
byId('adjustment-form').addEventListener('submit',event=>{if(!adjustmentItems.size){event.preventDefault();byId('adjustment-message').textContent='Add at least one product size to adjust.';byId('adjustment-message').classList.remove('hidden');return;}byId('submit-adjustment').disabled=true;byId('submit-adjustment').textContent='Saving…';});
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));}
</script>
@endsection
